import { test, expect, type Page } from "@playwright/test";
import { execFileSync } from "node:child_process";
import { resolve } from "node:path";

// Results are generated by the existing, unchanged backend graders and source data.
const fixtures = JSON.parse(execFileSync(resolve("../backend/.venv/bin/python"), ["-c", `
import json
from pathlib import Path
from app.modules.listening.grading import result_for as listening_result
from app.modules.reading.grading import result_for as reading_result, estimated_band
from app.modules.reading.catalog import ReadingCatalog
root=Path('app/content/listening_v1')
eid='cambridge-14-test-01'
exam=json.loads((root/'exams'/f'{eid}.json').read_text())
key=json.loads((root/'keys'/f'{eid}.json').read_text())
l=listening_result({'exam':exam,'key':key,'mode':'verified'}, {})
l['exam']=exam
catalog=ReadingCatalog()
eid='cambridge-18-test-01'
snapshot={'exam':catalog.exams[eid],'key':catalog.keys[eid],'metadata':catalog.entries[eid]}
r=reading_result(snapshot,{},'full_exam',None,120,{})
print(json.dumps({'listening':l,'reading':r,'readingExam':catalog.public_exam(snapshot['exam']),'hash':snapshot['metadata']['content_hash'],'readingBands':[estimated_band(n) for n in range(41)]}))
`], { cwd: resolve("../backend"), encoding: "utf8" }));
const oldId = "11111111-2222-4333-8444-555555555555", newId = "22222222-2222-4333-8444-555555555555";

async function load(page: Page, section: "reading" | "listening", score = 30, partial = false, unknownCreate = false) {
  const isReading = section === "reading";
  const result = structuredClone(fixtures[section]);
  const exam = isReading ? fixtures.readingExam : result.exam;
  const examId = isReading ? exam.id : exam.exam_id;
  const positions = isReading ? result.positions : result.questions;
  positions.forEach((p: Record<string, unknown>, i: number) => { p[isReading ? "is_correct" : "correct"] = i < score; });
  if (isReading) { result.raw_score = score; result.estimated_band = fixtures.readingBands[score]; }
  else {
    result.correct_count = score;
    result.graded_count = partial ? 10 : 40;
    result.estimated_band = partial ? 9 : result.band_table.find(([cutoff]: number[]) => score >= cutoff!)?.[1] ?? null;
    if (partial) result.questions[20].correct = null;
  }
  result.attempt_id = oldId;
  if (isReading) result.completion_reason = "submitted";
  const attempt = { id: oldId, exam_id: examId, content_hash: isReading ? fixtures.hash : "fixture-hash", status: "submitted", mode: isReading ? "full_exam" : "verified", version: 1,
    server_now: new Date().toISOString(), deadline_at: new Date(Date.now() + 3600000).toISOString(), answers: {}, state: isReading ? { current_passage: 1, checked_question_ids: [] } : { displayed_part: 1, current_question: 1, audio_part: 1, playback_seconds: 0, marked: [] }, not_fully_proofread: true, exam };
  const posts: Record<string, unknown>[] = [];
  await page.route("**/api/alua/**", async route => {
    const req = route.request(), path = new URL(req.url()).pathname;
    if (req.method() === "POST") {
      posts.push(req.postDataJSON());
      if (unknownCreate && posts.length === 1) { await route.abort("failed"); return; }
      await route.fulfill({ status: 201, json: { ...attempt, id: newId, status: "in_progress", answers: {} } }); return;
    }
    if (path.endsWith("/review") || path.endsWith("/result")) { await route.fulfill({ json: result }); return; }
    if (path.includes("/assets/")) { await route.fulfill({ status: 404 }); return; }
    await route.fulfill({ json: path.endsWith(newId) ? { ...attempt, id: newId, status: "in_progress", answers: {} } : attempt });
  });
  const url = `/${section}/attempts/${oldId}/${isReading ? "result" : "results"}`;
  await page.goto(url);
  await expect(page.getByRole("region", { name: "Test result" })).toBeVisible();
  return { posts, url, result };
}

for (const section of ["listening", "reading"] as const) {
  test(`${section}: minimal centred result, badge, responsive and Review`, async ({ page }, info) => {
    const { posts } = await load(page, section);
    await expect(page.getByLabel("Estimated IELTS band score", { exact: true })).toHaveText("7.0");
    await expect(page.getByText("30 correct · 10 incorrect")).toBeVisible();
    await expect(page.getByRole("heading")).toHaveText(section === "listening" ? "Cambridge 14 · Test 1" : "Cambridge 18 · Test 1");
    await expect(page.getByText("Question breakdown")).toHaveCount(0);
    const layout = await page.evaluate(() => {
      const card = document.querySelector('section[aria-label="Test result"]')!.getBoundingClientRect();
      const review = document.querySelector('a[href$="/review"]')!;
      const button = review.getBoundingClientRect(), text = review.firstElementChild!.getBoundingClientRect();
      const badge = review.lastElementChild!.getBoundingClientRect();
      const retake = document.querySelector('button[aria-busy]')!.getBoundingClientRect();
      return { overflowX: document.documentElement.scrollWidth > innerWidth, overflowY: document.documentElement.scrollHeight > innerHeight,
        cx: card.x + card.width / 2 - innerWidth / 2, cy: card.y + card.height / 2 - innerHeight / 2,
        textX: text.x + text.width / 2 - button.x - button.width / 2, textY: text.y + text.height / 2 - button.y - button.height / 2,
        heightDifference: button.height - retake.height, badgeAbove: badge.y < button.y, badgeClear: badge.bottom <= text.y, width: card.width };
    });
    expect(layout.overflowX).toBe(false); expect(layout.overflowY).toBe(false);
    for (const n of [layout.cx, layout.cy, layout.textX, layout.textY, layout.heightDifference]) expect(Math.abs(n)).toBeLessThanOrEqual(1);
    expect(layout.badgeAbove).toBe(true); expect(layout.badgeClear).toBe(true); expect(layout.width).toBeLessThanOrEqual(480);
    await page.screenshot({ path: `test-results-results-v2/${section}-${info.project.name}.png` });
    await page.getByRole("link", { name: /Review test/ }).click();
    await expect(page).toHaveURL(new RegExp(`/${section}/attempts/${oldId}/review$`));
    await expect(page.getByRole("region", { name: "Test result" })).toHaveCount(0);
    expect(posts).toHaveLength(0);
  });
  test(`${section}: fresh Retake, double-click guarded, previous result retained`, async ({ page }) => {
    const { posts, url } = await load(page, section);
    await page.getByRole("button", { name: "Retake test" }).dblclick();
    await expect(page).toHaveURL(new RegExp(`/${section}/attempts/${newId}$`));
    expect(posts).toHaveLength(1); expect(posts[0]!.reuse_active).toBe(false);
    expect(posts[0]!.exam_id).toBe(section === "reading" ? "cambridge-18-test-01" : "cambridge-14-test-01");
    await page.goto(url); await expect(page.getByText("30 correct · 10 incorrect")).toBeVisible();
  });
  test(`${section}: unknown Retake response retries same event`, async ({ page }) => {
    const { posts } = await load(page, section, 30, false, true);
    await page.getByRole("button", { name: "Retake test" }).click();
    await expect(page.getByRole("alert").filter({ hasText: "Couldn’t start" })).toContainText("Couldn’t start");
    await page.getByRole("button", { name: "Retake test" }).click();
    await expect(page).toHaveURL(new RegExp(`/${section}/attempts/${newId}$`));
    expect(posts).toHaveLength(2); expect(posts[0]).toEqual(posts[1]);
  });
  test(`${section}: subject table boundary 32 and below range`, async ({ page }) => {
    await load(page, section, 32);
    await expect(page.getByLabel("Estimated IELTS band score", { exact: true })).toHaveText(section === "reading" ? "7.0" : "7.5");
    await page.unroute("**/api/alua/**"); await load(page, section, 0);
    await expect(page.getByLabel("Estimated IELTS band score", { exact: true })).toHaveText("—");
    await expect(page.getByText("0 correct · 40 incorrect")).toBeVisible();
  });
}
test("Listening: unconfirmed grading suppresses band and summary counts", async ({ page }) => {
  await load(page, "listening", 8, true);
  await expect(page.getByLabel("Estimated IELTS band score", { exact: true })).toHaveText("—");
  await expect(page.getByText("Grading not confirmed", { exact: true })).toBeVisible();
  await expect(page.getByText(/\d+ correct · \d+ incorrect/)).toHaveCount(0);
});
